  Thought: I need to perform a permutation test with at least 500 shuffles to assess significance. For each borough, I'll shuffle z-scores across all boroughs, recompute local Moran's I, and calculate a one-sided p-value for positive spatial autocorrelation. Then I'll identify significant HH (z>0, lag>0) and LL (z<0, lag<0) clusters.
Action:
```python
import pandas as pd
import numpy as np

DATASET_PATH = 'chunks_csv/moran_local_2023_energy.csv'
ADJACENCY_PATH = 'chunks_csv/borough_adjacency.csv'

df = pd.read_csv(DATASET_PATH)
adj = pd.read_csv(ADJACENCY_PATH)

# Build neighbor dictionary
neighbors = {}
for b in df['borough'].unique():
    neighbors[b] = set()

for _, row in adj.iterrows():
    b = row['borough']
    n = row['neighbor']
    if b in neighbors and n in neighbors:
        neighbors[b].add(n)
        neighbors[n].add(b)

boroughs = df['borough'].tolist()
n = len(boroughs)
idx_map = {b: i for i, b in enumerate(boroughs)}

# Compute z-scores
values = np.array([dict(zip(df['borough'], df['Energy_value']))[b] for b in boroughs])
z = (values - np.mean(values)) / np.std(values, ddof=0)

# Precompute neighbor indices for each borough
neighbor_indices = []
for b in boroughs:
    neighbor_indices.append([idx_map[nbr] for nbr in neighbors[b]])

# Compute observed local Moran's I
observed_I = np.zeros(n)
for i in range(n):
    if len(neighbor_indices[i]) > 0:
        lag = np.mean(z[neighbor_indices[i]])
        observed_I[i] = z[i] * lag
    else:
        observed_I[i] = 0

# Permutation test: 500 shuffles
n_perm = 500
perm_I = np.zeros((n_perm, n))

np.random.seed(42)
for p in range(n_perm):
    z_perm = np.random.permutation(z)
    for i in range(n):
        if len(neighbor_indices[i]) > 0:
            lag = np.mean(z_perm[neighbor_indices[i]])
            perm_I[p, i] = z_perm[i] * lag
        else:
            perm_I[p, i] = 0

# One-sided p-value: proportion of permutations with I >= observed I
# (since we're testing for positive spatial autocorrelation)
p_values = np.mean(perm_I >= observed_I, axis=0)

# Determine categories
categories = []
for i in range(n):
    if len(neighbor_indices[i]) == 0:
        categories.append('NA')
    elif z[i] > 0 and np.mean(z[neighbor_indices[i]]) > 0:
        categories.append('HH')
    elif z[i] < 0 and np.mean(z[neighbor_indices[i]]) < 0:
        categories.append('LL')
    elif z[i] > 0 and np.mean(z[neighbor_indices[i]]) < 0:
        categories.append('HL')
    elif z[i] < 0 and np.mean(z[neighbor_indices[i]]) > 0:
        categories.append('LH')
    else:
        categories.append('NA')

# Print results
print(f"{'Borough':<30} {'z':>8} {'lag':>8} {'I':>8} {'p-value':>8} {'cat':>4}")
print("-" * 70)
for i in range(n):
    lag = np.mean(z[neighbor_indices[i]]) if len(neighbor_indices[i]) > 0 else 0
    print(f"{boroughs[i]:<30} {z[i]:8.4f} {lag:8.4f} {observed_I[i]:8.4f} {p_values[i]:8.4f} {categories[i]:>4}")

print("\nSignificant HH (p < 0.05):")
for i in range(n):
    if categories[i] == 'HH' and p_values[i] < 0.05:
        print(f"  {boroughs[i]}: I={observed_I[i]:.4f}, p={p_values[i]:.4f}")

print("\nSignificant LL (p < 0.05):")
for i in range(n):
    if categories[i] == 'LL' and p_values[i] < 0.05:
        print(f"  {boroughs[i]}: I={observed_I[i]:.4f}, p={p_values[i]:.4f}")
```
